def generate_hypotheses(subgoals, n_hypotheses=5):
    hypotheses = []
    for i in range(n_hypotheses):
        hyp = {sg: np.random.choice([True, False]) for sg in subgoals}
        hypotheses.append(hyp)
    return hypotheses

hypotheses = generate_hypotheses(subgoals)
for i, h in enumerate(hypotheses):
    print(f"Hypothesis {i+1}: {h}")

def evaluate_hypothesis(hypothesis, probabilities):
    score = 1.0
    for i, sg in enumerate(subgoals):
        if hypothesis[sg]:
            score *= probabilities[i]
        else:
            score *= (1 - probabilities[i])
    return score

scores = [evaluate_hypothesis(h, probabilities) for h in hypotheses]
print("Scores of hypotheses:", [round(s, 2) for s in scores])

def reinforce_hypothesis(hypothesis, probabilities, learning_rate=0.1):
    updated = {}
    for i, sg in enumerate(subgoals):
        if hypothesis[sg]:
            updated[sg] = probabilities[i] + learning_rate
        else:
            updated[sg] = probabilities[i]
    return updated

